import math
T = int(input())
for i in range(T):
	N = int(input())
	B = list(map(int, input().split()))

	def fun(i):
		t = False
		for j in B:
			if math.gcd(i + 1, j) == B[i]:
				t = True
				break
		return t
	c = 0
	for i in range(N):
		if B[i] == i + 1 or fun(i) == True:
			c = c + 1
		else:
			print('NO')
			break
	if c == N:
		print('YES')
